"use client";

import { useEffect, useId, useRef } from "react";
import { EMPTY_ART, type EmptyArtName } from "@/components/app/empty-art-data";
import { cn } from "@/lib/utils";

export type { EmptyArtName };

/**
 * The picture above an empty state: an isometric object on a soft hexagon, with a small badge.
 *
 * IN THE CONTRACTOR'S OWN BRAND COLOUR. The artwork is generated by `scripts/build-empty-art.mjs`
 * with every fill a CSS variable, so it is drawn inline rather than as an `<img>`, which could not
 * read the page's `--brand`. Colours and the entrance animation live in globals.css under
 * `.empty-art`.
 *
 * TWO MOVEMENTS, BOTH QUIET. It plays an entrance once (CSS), then leans up to 3px toward the mouse
 * while the backdrop shifts 1px the other way (below), which reads as depth. No looping motion: an
 * empty state sits on a screen people work on, and something that never stops moving pulls the eye
 * off the work. Both are off under reduced motion, and the lean is off on touch, where there is no
 * pointer to follow.
 *
 * THE BADGE SAYS WHAT EMPTY MEANS: `plus` when you can make the first one, `check` when empty is
 * good news (nothing owed, inbox clear), `x` for a search that missed. Each picture has a default;
 * pass `badge` when the screen means something else by it, and `none` when there is no action
 * (a crew member looking at jobs nobody has assigned them).
 */
export function EmptyArt({
  name,
  badge,
  className,
}: {
  name: EmptyArtName;
  badge?: "plus" | "check" | "x" | "none";
  className?: string;
}) {
  const art = EMPTY_ART[name];
  const dots = `dots${useId().replace(/[^a-zA-Z0-9]/g, "")}`;
  const objectRef = useRef<SVGGElement>(null);
  const blobRef = useRef<SVGGElement>(null);
  const shown = badge ?? art.badge;

  useEffect(() => {
    const object = objectRef.current;
    const blob = blobRef.current;
    if (!object || !blob) return;
    if (!matchMedia("(pointer: fine)").matches) return;
    if (matchMedia("(prefers-reduced-motion: reduce)").matches) return;

    let frame = 0;
    const onMove = (event: PointerEvent) => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => {
        const x = (event.clientX / innerWidth) * 2 - 1;
        const y = (event.clientY / innerHeight) * 2 - 1;
        object.style.translate = `${x * 3}px ${y * 3}px`;
        blob.style.translate = `${-x}px ${-y}px`;
      });
    };
    addEventListener("pointermove", onMove);
    return () => {
      cancelAnimationFrame(frame);
      removeEventListener("pointermove", onMove);
    };
  }, []);

  return (
    <svg
      viewBox="0 0 160 160"
      aria-hidden
      className={cn("empty-art size-40 shrink-0 overflow-visible", className)}
    >
      <defs>
        <pattern id={dots} width="3.2" height="3.2" patternUnits="userSpaceOnUse" patternTransform="rotate(30)">
          <circle cx="1.6" cy="1.6" r="0.7" fill="var(--art-ink)" opacity="0.55" />
        </pattern>
      </defs>

      {/* A hexagon whose corners are rounded by a fat stroke in its own colour. The opacity sits on
          the group so the fill and the stroke composite once, rather than as two layers with a
          darker ring where they overlap. */}
      <g ref={blobRef} className="empty-art-blob" opacity={0.24}>
        <polygon points={HEXAGON} fill="var(--brand)" stroke="var(--brand)" strokeWidth={22} strokeLinejoin="round" />
      </g>

      <g
        ref={objectRef}
        className="empty-art-object"
        // Safe: the markup is generated at build time from fixed scenes in
        // `scripts/build-empty-art.mjs`. No user input reaches it.
        dangerouslySetInnerHTML={{ __html: art.body.replaceAll("#DOTS", `#${dots}`) }}
      />

      {shown !== "none" ? (
        <g className="empty-art-badge">
          <g transform="translate(127 38)">
            <circle r={11} fill="var(--art-front)" stroke="var(--art-ink)" strokeWidth={2.4} />
            <path
              d={BADGE[shown]}
              fill="none"
              stroke="var(--art-ink)"
              strokeWidth={2.4}
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </g>
        </g>
      ) : null}
    </svg>
  );
}

const HEXAGON = Array.from({ length: 6 }, (_, i) => {
  const a = Math.PI / 6 + (i * Math.PI) / 3;
  return `${(80 + 57 * Math.cos(a)).toFixed(1)},${(80 + 57 * Math.sin(a)).toFixed(1)}`;
}).join(" ");

const BADGE = {
  plus: "M-4.5 0h9M0 -4.5v9",
  check: "M-4.6 0.2l3 3 6.2-6.4",
  x: "M-3.6 -3.6l7.2 7.2M3.6 -3.6l-7.2 7.2",
} as const;
